import {events,dateKey,isUnlocked,nextSurprise,openingTime} from './calendar.mjs?v=jantar-3';
const previewMode=location.pathname.endsWith('/previa.html')||new URLSearchParams(location.search).get('previa')==='1';
const canOpen=(date,now=new Date())=>previewMode||isUnlocked(date,now);
const $=s=>document.querySelector(s);const timeline=$('#timeline');const dialog=$('#surprise-dialog');let lastKey='';let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4000);}
function confetti(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const box=$('#confetti');box.replaceChildren();for(let i=0;i<45;i++){const p=document.createElement('span');p.className='confetto';p.style.left=Math.random()*100+'%';p.style.background=['#b72f60','#e6a6c0','#eabf75','#f6d6e1'][i%4];p.style.animationDelay=Math.random()*.5+'s';p.style.setProperty('--drift',(Math.random()-.5)*300+'px');box.append(p);}setTimeout(()=>box.replaceChildren(),3500);}
function openEvent(event){if(!canOpen(event.date)){toast('Esse segredinho abre em '+event.day+'/'+(event.month==='out'?'10':'11')+'. Nada de espiar, hein? ♡');return;}$('#dialog-content').innerHTML='<img class="reveal-photo" src="assets/'+event.photo+'" alt="Uma lembrança da Aline"><div class="reveal-body"><span class="reveal-tag">'+event.weekday+' · '+event.day+' '+event.month+'</span><h2 id="dialog-title">'+event.title+'</h2><p>'+event.message+'</p><div class="reveal-extra">'+event.note+'</div><button class="pill" id="celebrate">Amei. Pode comemorar! ♡</button></div>';dialog.showModal();$('#celebrate').addEventListener('click',()=>{confetti();toast('Mais uma memória bonita para a nossa coleção. ♡');});confetti();}
function render(){const now=new Date();const key=dateKey(now);if(key!==lastKey){timeline.replaceChildren();for(const event of events){const unlocked=canOpen(event.date,now);const button=document.createElement('button');button.className='day-card '+(unlocked?'unlocked':'locked')+(event.date===key?' today':'');button.setAttribute('aria-label',event.weekday+', '+event.day+' de '+event.month+': '+(unlocked?event.title:'surpresa bloqueada'));if(!unlocked)button.setAttribute('aria-disabled','true');button.innerHTML='<span class="weekday">'+event.weekday+'</span><span class="day">'+event.day+'<small>'+event.month+'</small></span><span class="card-state">'+(unlocked?'♡':'⌑')+'</span><span class="card-icon" aria-hidden="true">'+(unlocked?event.icon:'✉')+'</span><h3>'+(unlocked?event.title:'Segredinho #'+event.number)+'</h3><div class="card-bottom">'+(unlocked?'Abrir minha surpresa ↗':'Abre em '+event.day+'/'+(event.month==='out'?'10':'11')+' · sem espiar!')+'</div>';button.addEventListener('click',()=>openEvent(event));timeline.append(button);}lastKey=key;}
const next=previewMode?null:nextSurprise(events,now);const opened=events.filter(e=>canOpen(e.date,now)).length;$('#status-title').textContent=previewMode?'Prévia do Poso: todas as surpresas liberadas ♡':opened===0?'A contagem regressiva mais bonita começou.':opened===events.length?'Todos os seus segredinhos foram revelados!':opened+' de 5 surpresas já podem ser abertas ♡';$('#status-description').textContent=previewMode?'Você está no modo de prévia. No link sem ?previa=1, as datas continuam valendo.':next?'A próxima se revela em '+next.day+'/'+(next.month==='out'?'10':'11')+'. Até lá, pode ficar curiosa.':'Agora é guardar cada pedacinho desses dias no coração.';
if(next){const sec=Math.max(0,Math.floor((openingTime(next.date)-now.getTime())/1000));const d=Math.floor(sec/86400);const h=String(Math.floor(sec%86400/3600)).padStart(2,'0');const m=String(Math.floor(sec%3600/60)).padStart(2,'0');const s=String(sec%60).padStart(2,'0');$('#countdown').textContent=(d?d+'d ':'')+h+'h '+m+'m '+s+'s';}else $('#countdown').textContent='♡';}
$('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});$('#more-photos').addEventListener('click',()=>{const gallery=$('#extra-gallery');if(!gallery.childElementCount){for(const [file,alt]of [['aline-01.png','Aline em um momento tranquilo'],['aline-07.png','Aline concentrada no celular'],['aline-11.png','Um retrato da Aline'],['aline-04.png','Aline tirando uma soneca'],['aline-13.png','Aline aproveitando um dia de sol']]){const img=document.createElement('img');img.src='assets/'+file;img.alt=alt;img.loading='lazy';gallery.append(img);}}gallery.hidden=!gallery.hidden;$('#more-photos').innerHTML=gallery.hidden?'Mais um pouquinho dela <span>＋</span>':'Guardar as fotinhos <span>−</span>';$('#more-photos').setAttribute('aria-expanded',String(!gallery.hidden));});$('#more-photos').setAttribute('aria-expanded','false');$('#more-photos').setAttribute('aria-controls','extra-gallery');document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});render();setInterval(render,1000);
